const rows = Array.isArray($json.list) ? $json.list : [];
const enabled = String($env.RAYN_INSTANTLY_SYNC_ENABLED || '').trim().toLowerCase() === 'true';
const apiKey = String($env.INSTANTLY_API_KEY || '').trim();
const campaignId = String($env.INSTANTLY_CAMPAIGN_ID || '').trim();
function text(value) { return String(value || '').trim(); }
function boolish(value) { return value === true || text(value).toLowerCase() === 'true'; }
function hasFlags(value) {
  try {
    const parsed = Array.isArray(value) ? value : JSON.parse(text(value) || '[]');
    return Array.isArray(parsed) && parsed.length > 0;
  } catch {
    return Boolean(text(value));
  }
}
function splitName(value) {
  const parts = text(value).split(/\s+/).filter(Boolean);
  if (!parts.length) return { first_name: '', last_name: '' };
  if (parts.length === 1) return { first_name: parts[0], last_name: '' };
  return { first_name: parts[0], last_name: parts.slice(1).join(' ') };
}
function escapeHtml(value) {
  return text(value).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}
function bodyHtml(value) {
  return escapeHtml(value).split(/\n{2,}/).map((part) => part.replace(/\n/g, '<br />')).filter(Boolean).map((part) => `<p>${part}</p>`).join('');
}
if (!enabled || !apiKey || !campaignId) return [];
const candidates = [];
for (const row of rows) {
  if (!row || !row.Id) continue;
  if (!boolish(row.email_send_ready)) continue;
  if (text(row.automation_decision) !== 'auto_send_eligible') continue;
  if (!boolish(row.final_send_gate_passed)) continue;
  if (boolish(row.do_not_contact)) continue;
  if (text(row.unsubscribe_status || 'active') !== 'active') continue;
  if (text(row.send_provider) === 'instantly') continue;
  if (['synced', 'skipped'].includes(text(row.instantly_sync_status))) continue;
  if (hasFlags(row.severe_email_flags) || hasFlags(row.email_quality_flags)) continue;
  if (!text(row.validated_email) || !text(row.email_1_subject) || !text(row.email_1_body)) continue;
  candidates.push(row);
}
if (!candidates.length) return [];
candidates.sort((a, b) => Number(a.Id) - Number(b.Id));
const row = candidates[0];
const name = splitName(row.selected_contact_name);
const customVariables = {
  rayn_row_id: String(row.Id),
  email_1_subject: text(row.email_1_subject),
  email_1_body: text(row.email_1_body),
  email_1_body_html: bodyHtml(row.email_1_body),
  email_2_subject: text(row.email_2_subject),
  email_2_body: text(row.email_2_body),
  email_2_body_html: bodyHtml(row.email_2_body),
  selected_contact_role: text(row.selected_contact_role || row.selected_contact_title),
  source: 'rayn_nocodb'
};
return [{ json: {
  Id: row.Id,
  company_name: text(row.company_name),
  recipient_email: text(row.validated_email),
  campaign_id: campaignId,
  instantly_body: {
    campaign: campaignId,
    email: text(row.validated_email),
    first_name: name.first_name,
    last_name: name.last_name,
    company_name: text(row.company_name),
    job_title: text(row.selected_contact_title || row.selected_contact_role),
    website: text(row.best_url),
    skip_if_in_workspace: true,
    skip_if_in_campaign: true,
    skip_if_in_list: true,
    custom_variables: customVariables
  }
} }];

const preparedItems = $('Prepare Instantly Lead').all();
const now = new Date().toISOString();
function text(value) { return String(value || '').trim(); }
function errorText(payload) {
  if (!payload) return 'Instantly request failed';
  if (typeof payload === 'string') return payload;
  return text(payload.message || payload.error || payload.detail || JSON.stringify(payload));
}
function providerAccountError(value) {
  const message = errorText(value).toLowerCase().replace(/[_-]+/g, ' ');
  return /provider_account_error|insufficient balance|zero balance|balance not enough|no funds|out of funds|insufficient funds|quota|billing|payment required|invalid api key|invalid key|wrong api key|api key|unauthorized|too many requests|rate limit/.test(message);
}
const patches = [];
for (const [index, item] of $input.all().entries()) {
  const source = preparedItems[index]?.json || {};
  const response = item.json || {};
  const leadId = text(response.id || response.lead_id || response.data?.id);
  const ok = Boolean(leadId) && !response.error && !response.message?.toLowerCase?.().includes('error');
  const patch = {
    Id: source.Id,
    send_provider: 'instantly',
    instantly_campaign_id: source.campaign_id,
    send_last_attempted_at: now
  };
  if (ok) {
    patch.instantly_lead_id = leadId;
    patch.instantly_sync_status = 'synced';
    patch.instantly_sync_error = '';
    patch.instantly_synced_at = now;
    patch.sequence_status = 'queued';
    patch.send_status = 'queued';
  } else {
    const syncError = errorText(response);
    if (providerAccountError(response)) {
      throw new Error('provider_account_error: Instantly lead sync failed: ' + syncError);
    }
    patch.instantly_sync_status = 'failed_retryable';
    patch.instantly_sync_error = syncError;
    patch.sequence_status = 'failed';
    patch.send_status = 'failed_retryable';
    patch.send_error = patch.instantly_sync_error;
  }
  patches.push(patch);
}
return patches.map((patch) => ({ json: patch }));
